SELECT id, spam_text, category, CASE WHEN vector_json IS NOT NULL AND vector_json != '' THEN 1 ELSE 0 END as has_vector, memo, created_at, updated_at FROM t_defense WHERE 1=1
AND (spam_text LIKE '%' || #{keyword} || '%' OR memo LIKE '%' || #{keyword} || '%')
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT id, spam_text
FROM t_defense
WHERE TRIM(spam_text) = #{spam_text}
